class NumArray {
    vector<int> tree;
    vector<int> arr;
    int n;

    void add(int i, int delta) {
        for (++i; i <= n; i += i & (-i))
            tree[i] += delta;
    }

    int prefix(int i) {
        int s = 0;
        for (++i; i > 0; i -= i & (-i))
            s += tree[i];
        return s;
    }

public:
    NumArray(vector<int>& nums) {
        n = nums.size();
        arr = nums;
        tree.assign(n + 1, 0);
        for (int i = 0; i < n; ++i)
            add(i, nums[i]);
    }

    void update(int index, int val) {
        add(index, val - arr[index]);
        arr[index] = val;
    }

    int sumRange(int left, int right) {
        return prefix(right) - (left > 0 ? prefix(left - 1) : 0);
    }
};
